PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "role" varchar, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "ccd_budgets" ("budget_hash" varchar not null, "master_ik" varchar not null, "t1" numeric, "t2" numeric, "t3" numeric, "t4" numeric, "t5" numeric, "ct1_tw1" numeric not null default '0', "ct1_tw2" numeric not null default '0', "ct1_tw3" numeric not null default '0', "ct1_tw4" numeric not null default '0', "ct2_tw1" numeric not null default '0', "ct2_tw2" numeric not null default '0', "ct2_tw3" numeric not null default '0', "ct2_tw4" numeric not null default '0', "ct3_tw1" numeric not null default '0', "ct3_tw2" numeric not null default '0', "ct3_tw3" numeric not null default '0', "ct3_tw4" numeric not null default '0', "ct4_tw1" numeric not null default '0', "ct4_tw2" numeric not null default '0', "ct4_tw3" numeric not null default '0', "ct4_tw4" numeric not null default '0', "ct5_tw1" numeric not null default '0', "ct5_tw2" numeric not null default '0', "ct5_tw3" numeric not null default '0', "ct5_tw4" numeric not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("master_ik") references "ccd_indicators"("master_ik"), primary key ("budget_hash"));
CREATE TABLE IF NOT EXISTS "ccd_descs" (
    "tahun" INTEGER NOT NULL DEFAULT 2025,
    "master_id" VARCHAR NOT NULL PRIMARY KEY,
    "tj_id" VARCHAR NOT NULL DEFAULT '00',
    "ss_id" VARCHAR NOT NULL DEFAULT '00',
    "pg_id" VARCHAR NOT NULL DEFAULT '00',
    "kg_id" VARCHAR NOT NULL DEFAULT '00',
    "sk_id" VARCHAR NOT NULL DEFAULT '00',
    "deskripsi_1" TEXT NOT NULL,
    "deskripsi_2" TEXT,
    "created_at" DATETIME,
    "updated_at" DATETIME,
    "deleted_at" DATETIME
);
CREATE TABLE IF NOT EXISTS "ccd_indicators" (
    "master_ik" VARCHAR NOT NULL PRIMARY KEY,
    "master_id" VARCHAR NOT NULL,
    "ik_id" VARCHAR(2) NOT NULL,
    "indikator" TEXT NOT NULL,
    "satuan" VARCHAR NOT NULL,
    "baseline" VARCHAR,
    "t1" FLOAT,
    "t2" FLOAT,
    "t3" FLOAT,
    "t4" FLOAT,
    "t5" FLOAT,
    "iku_alasan" TEXT,
    "iku_formulasi" TEXT,
    "iku_tipehitung" TEXT,
    "iku_do" TEXT,
    "iku_sumberdata" TEXT,
    "ct1_tw1" FLOAT NOT NULL DEFAULT 0.00,
    "ct1_tw2" FLOAT NOT NULL DEFAULT 0.00,
    "ct1_tw3" FLOAT NOT NULL DEFAULT 0.00,
    "ct1_tw4" FLOAT NOT NULL DEFAULT 0.00,
    "ct2_tw1" FLOAT NOT NULL DEFAULT 0.00,
    "ct2_tw2" FLOAT NOT NULL DEFAULT 0.00,
    "ct2_tw3" FLOAT NOT NULL DEFAULT 0.00,
    "ct2_tw4" FLOAT NOT NULL DEFAULT 0.00,
    "ct3_tw1" FLOAT NOT NULL DEFAULT 0.00,
    "ct3_tw2" FLOAT NOT NULL DEFAULT 0.00,
    "ct3_tw3" FLOAT NOT NULL DEFAULT 0.00,
    "ct3_tw4" FLOAT NOT NULL DEFAULT 0.00,
    "ct4_tw1" FLOAT NOT NULL DEFAULT 0.00,
    "ct4_tw2" FLOAT NOT NULL DEFAULT 0.00,
    "ct4_tw3" FLOAT NOT NULL DEFAULT 0.00,
    "ct4_tw4" FLOAT NOT NULL DEFAULT 0.00,
    "ct5_tw1" FLOAT NOT NULL DEFAULT 0.00,
    "ct5_tw2" FLOAT NOT NULL DEFAULT 0.00,
    "ct5_tw3" FLOAT NOT NULL DEFAULT 0.00,
    "ct5_tw4" FLOAT NOT NULL DEFAULT 0.00,
    "created_at" DATETIME,
    "updated_at" DATETIME,
    "deleted_at" DATETIME,
    FOREIGN KEY("master_id") REFERENCES "ccd_descs"("master_id")
);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
COMMIT;
